fn cube_root(n: u8) -> u8 {
    // Precomputed cubes for 0 through 6:
    // 0^3 = 0, 1^3 = 1, 2^3 = 8, 3^3 = 27,
    // 4^3 = 64, 5^3 = 125, 6^3 = 216.
    const CUBES: [u8; 7] = [0, 1, 8, 27, 64, 125, 216];

    // Iterate from the largest possible root (6) down to 0,
    // returning the first r such that r^3 <= n.
    for i in (0..CUBES.len()).rev() {
        if CUBES[i] <= n {
            return i as u8;
        }
    }

    // This point is never reached, because when i == 0, CUBES[0] == 0 <= n.
    0
}

